#ifndef POINTDATA_HPP_
#define POINTDATA_HPP_

#include <stdint.h>
#include <vector>
#include <iostream>

struct PointData
{
  // Polar coordinate representation
  float angle;
  uint16_t distance;
  uint8_t confidence;

  // Rectangular coordinate representation
  double x;
  double y;

  PointData(float angle, uint16_t distance, uint8_t confidence, double x = 0, double y = 0)
  {
    this->angle = angle;
    this->distance = distance;
    this->confidence = confidence;
    this->x = x;
    this->y = y;
  }

  PointData()
  {
  }

  friend std::ostream & operator<<(std::ostream & os, const PointData & data)
  {
    os << data.angle << " " \
       << data.distance << " " \
       << static_cast<int>(data.confidence) << " " \
       << data.x << " " \
       << data.y;
    return os;
  }
};


typedef std::vector<PointData> Points2D;

#endif  // POINTDATA_HPP_

