  0xb7, 0x5d, 0x10, 0xc7, 0x8a, 0x24, 0x69, 0xbe, 0xf3, 0xaf, 0xe2, 0x35,
  0x78, 0xd6, 0x9b, 0x4c, 0x01, 0xf4, 0xb9, 0x6e, 0x23, 0x8d, 0xc0, 0x17,
  0x5a, 0x06, 0x4b, 0x9c, 0xd1, 0x7f, 0x32, 0xe5, 0xa8
};


LiPkg::LiPkg()
: mTimestamp(0), mSpeed(0), mErrorTimes(0), mIsFrameReady(false), mIsPkgReady(false)
{
}

double LiPkg::GetSpeed(void)
{
  return mSpeed / 360.0;
}

bool LiPkg::Parse(const uint8_t * data, int32_t len)
{
  for (int i = 0; i < len; i++) {
    mDataTmp.push_back(*(data + i));
  }

  if (mDataTmp.size() < sizeof(LiDARFrameTypeDef)) {
    return false;
  }

  if (mDataTmp.size() > sizeof(LiDARFrameTypeDef) * 100) {
    mErrorTimes++;
    mDataTmp.clear();
    return false;
  }

  uint16_t start = 0;

  while (start < mDataTmp.size() - 2) {
    start = 0;
    while (start < mDataTmp.size() - 2) {
      if ((mDataTmp[start] == PKG_HEADER) && (mDataTmp[start + 1] == PKG_VER_LEN)) {
        break;
      }

      if ((mDataTmp[start] == PKG_HEADER) &&
        (mDataTmp[start + 1] == (PKG_VER_LEN | (0x07 << 5))
        ))
      {
        break;
      }
      start++;
    }

    if (start != 0) {
      mErrorTimes++;
      for (int i = 0; i < start; i++) {
        mDataTmp.erase(mDataTmp.begin());
      }
    }

    if (mDataTmp.size() < sizeof(LiDARFrameTypeDef)) {
      return false;
    }

    LiDARFrameTypeDef * pkg = reinterpret_cast<LiDARFrameTypeDef *>(mDataTmp.data());
    uint8_t crc = 0;

    for (uint32_t i = 0; i < sizeof(LiDARFrameTypeDef) - 1; i++) {
      crc = CrcTable[(crc ^ mDataTmp[i]) & 0xff];
    }

    if (crc == pkg->crc8) {
      double diff = (pkg->end_angle / 100 - pkg->start_angle / 100 + 360) % 360;
      if (diff > static_cast<double>(pkg->speed) * POINT_PER_PACK / 2300 * 3 / 2) {
        mErrorTimes++;
      } else {
        mSpeed = pkg->speed;
        mTimestamp = pkg->timestamp;
        uint32_t diff =
          ((uint32_t)pkg->end_angle + 36000 - (uint32_t)pkg->start_angle) % 36000;
        float step = diff / (POINT_PER_PACK - 1) / 100.0;
        float start = static_cast<double>(pkg->start_angle) / 100.0;
        float end = static_cast<double>(pkg->end_angle % 36000) / 100.0;
        PointData data;
        for (int i = 0; i < POINT_PER_PACK; i++) {
          data.distance = pkg->point[i].distance;
          data.angle = start + i * step;
          if (data.angle >= 360.0) {
            data.angle -= 360.0;
          }
          data.confidence = pkg->point[i].confidence;
          mOnePkg[i] = data;
          mFrameTemp.push_back(PointData(data.angle, data.distance, data.confidence));
        }
        // prevent angle invert
        mOnePkg.back().angle = end;

        mIsPkgReady = true;
      }

      for (uint32_t i = 0; i < sizeof(LiDARFrameTypeDef); i++) {
        mDataTmp.erase(mDataTmp.begin());
      }

      if (mDataTmp.size() < sizeof(LiDARFrameTypeDef)) {
        break;
      }
    } else {
      mErrorTimes++;
      // only remove header,not all frame,because lidar data may contain head*/
      for (int i = 0; i < 2; i++) {
        mDataTmp.erase(mDataTmp.begin());
      }
    }
  }

  return true;
}

bool LiPkg::AssemblePacket()
{
  float last_angle = 0;
  std::vector<PointData> tmp;
  int count = 0;
  for (auto n = mFrameTemp.begin(); n != mFrameTemp.end(); n++) {
    // wait for enough data, need enough data to show a circle*/
    if ((*n).angle - last_angle < (-350.f)) {  // enough data has been obtained
      mFrameData.len = tmp.size();
      Transform(tmp);  // transform raw data to stantard data

      #ifdef USE_SLBI
      Slbi sb(2300);
      sb.FindBarcode(tmp);
      #endif

      #ifdef USE_SLBF
      Slbf sb(mSpeed);
      tmp = sb.NearFilter(tmp);
      #endif

      std::sort(
        tmp.begin(), tmp.end(), [](PointData a, PointData b) {return a.angle < b.angle;}
      );
      if (tmp.size() > 0) {
        ToLaserscan(tmp);
        mIsFrameReady = true;
        for (auto i = 0; i < count; i++) {
          mFrameTemp.erase(mFrameTemp.begin());
        }
        return true;
      }
    } else {
      tmp.push_back(*n);  //  getting data */
    }

    count++;
    last_angle = (*n).angle;
  }

  return false;
}

const std::array<PointData, POINT_PER_PACK> & LiPkg::GetPkgData(void)
{
  mIsPkgReady = false;
  return mOnePkg;
}

void LiPkg::ToLaserscan(std::vector<PointData> src)
{
  float angle_min, angle_max, range_min, range_max, angle_increment;

  // Adjust the parameters according to the demand
  angle_min = ANGLE_TO_RADIAN(src.front().angle);
  angle_max = ANGLE_TO_RADIAN(src.back().angle);
  range_min = 0.0;
  range_max = 100.0;

  angle_increment = ANGLE_TO_RADIAN(mSpeed / 2300);

  // Calculate the number of scanning points
  unsigned int beam_size = ceil((angle_max - angle_min) / angle_increment);
  output.angle_min = angle_min;
  output.angle_max = angle_max;
  output.range_min = range_min;
  output.range_max = range_max;
  output.angle_increment = angle_increment;
  // mSpeed = rotation_degree / sec
  output.time_increment = (360 / mSpeed) / ((angle_max - angle_min) / angle_increment);
  output.scan_time = 360 / mSpeed;

  // First fill all the data with Nan
  output.ranges.assign(beam_size, std::numeric_limits<float>::quiet_NaN());
  output.intensities.assign(beam_size, std::numeric_limits<float>::quiet_NaN());

  for (auto point : src) {
    float range = point.distance / 1000.f;
    float angle = ANGLE_TO_RADIAN(point.angle);

    float index = (angle - output.angle_min) / output.angle_increment;
    if (index >= 0.0 && index < beam_size) {
      // If the current content is Nan, it is assigned directly
      if (std::isnan(output.ranges[index])) {
        output.ranges[index] = range;
      } else {
        // Otherwise, only when the distance is less than the current value, it can be re assigned
        if (range < output.ranges[index]) {
          output.ranges[index] = range;
        }
      }
      output.intensities[index] = point.confidence;
    }
  }
}

